CREATE SCHEMA IF NOT EXISTS quorem_auth;
CREATE TABLE IF NOT EXISTS quorem_auth."user" (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, "emailVerified" boolean NOT NULL DEFAULT false, image text, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS quorem_auth."session" (id text PRIMARY KEY, "expiresAt" timestamptz NOT NULL, token text NOT NULL UNIQUE, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL, "ipAddress" text, "userAgent" text, "userId" text NOT NULL REFERENCES quorem_auth."user"(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS auth_session_user ON quorem_auth."session"("userId");
CREATE TABLE IF NOT EXISTS quorem_auth.account (id text PRIMARY KEY, "accountId" text NOT NULL, "providerId" text NOT NULL, "userId" text NOT NULL REFERENCES quorem_auth."user"(id) ON DELETE CASCADE, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" timestamptz, "refreshTokenExpiresAt" timestamptz, scope text, password text, "createdAt" timestamptz NOT NULL, "updatedAt" timestamptz NOT NULL, UNIQUE("providerId","accountId"));
CREATE TABLE IF NOT EXISTS quorem_auth.verification (id text PRIMARY KEY, identifier text NOT NULL, value text NOT NULL, "expiresAt" timestamptz NOT NULL, "createdAt" timestamptz, "updatedAt" timestamptz);
CREATE INDEX IF NOT EXISTS auth_verification_identifier ON quorem_auth.verification(identifier);
CREATE TABLE IF NOT EXISTS quorem_auth.jwks (id text PRIMARY KEY, "publicKey" text NOT NULL, "privateKey" text NOT NULL, "createdAt" timestamptz NOT NULL, "expiresAt" timestamptz);
ALTER TABLE quorem_auth.jwks ADD COLUMN IF NOT EXISTS alg text;
ALTER TABLE quorem_auth.jwks ADD COLUMN IF NOT EXISTS crv text;
